                    if all(0<=ay+a<H and 0<=ax+b<W and (inp[ay+a][ax+b]==bg or (ay+a,ax+b) in mks) for a,b in offs):
                        nxt.add((ay,ax))
        if not nxt: break
        cur|=nxt
    for (y,x) in sorted(cur):
        for a,b in offs:
            ii,jj=y+a,x+b
            if inp[ii][jj]==bg: out[ii][jj]=mk
    return out
for n in [6,7]:
    print(n, f(G[f'Demo pair {n} input'])==G[f'Demo pair {n} output'])

def f(inp):
    c=collections.Counter(x for row in inp for x in row)
    bg=c.most_common(1)[0][0]
    others=[v for v in c if v!=bg]
    pat=max(others,key=lambda v:c[v]); mk=min(others,key=lambda v:c[v])
    pps=[(i,j) for i,row in enumerate(inp) for j,v in enumerate(row) if v==pat]
    r0=min(i for i,j in pps); c0=min(j for i,j in pps)
    h_=max(i for i,j in pps)-r0+1; w_=max(j for i,j in pps)-c0+1
    offs=[(i-r0,j-c0) for i,j in pps]
    H,W=len(inp),len(inp[0])
    mks=set((i,j) for i,row in enumerate(inp) for j,v in enumerate(row) if v==mk)
    def valid(a,b):
        return all(0<=a+p<H and 0<=b+q<W and (inp[a+p][b+q]==bg or (a+p,b+q) in mks) for p,q in offs)
    out=[row[:] for row in inp]
    seeds=[]
    for ai in range(H-h_+1):
        for aj in range(W-w_+1):
            fr=[o for o in offs if (ai+o[0],aj+o[1]) in mks]
            free=[o for o in offs if not ((ai+o[0],aj+o[1]) in mks)]
            if len(fr)>0 and all((ai+o[0],aj+o[1]) in mks for o in fr) and valid(ai,aj):
                seeds.append((ai,aj))
    cur=set(seeds)
    dirs=[(h_,-w_),(-h_,w_)]
    for _ in range(min(3*(H+W),200)):
        nxt=set()
        for (y,x) in cur:
            for dy,dx in dirs:
                ay=ax=y+dy; ax=x+dx
                if 0<=ay<H-h_+1 and 0<=ax<W-w_+1 and (ay,ax) not in cur and valid(ay,ax):
                    nxt.add((ay,ax))
        if not nxt: break
        cur|=nxt
    for (y,x) in sorted(cur):
        for a,b in offs:
            ii,jj=y+a,x+b
            if inp[ii][jj]==bg: out[ii][jj]=mk
    return out
for n in [6,7]:
    print(n, f(G[f'Demo pair {n} input'])==G[f'Demo pair {n} output'])
